+const IDENT = "[0-9A-Za-z-]+";
+const VERSION_RE = new RegExp(
+  `^v?(\\d+)\\.(\\d+)\\.(\\d+)(?:-(${IDENT}(?:\\.${IDENT})*))?(?:\\+${IDENT}(?:\\.${IDENT})*)?$`,
+);
+
 /** Parse a version string. See README.md for the accepted syntax. */
 export function parseVersion(text: string): Version {
-  throw new Error("not implemented");
+  const match = VERSION_RE.exec(text.trim());
+  if (!match) {
+    throw new Error(`invalid version: ${JSON.stringify(text)}`);
+  }
+  return {
+    major: Number(match[1]),
+    minor: Number(match[2]),
+    patch: Number(match[3]),
+    prerelease: match[4] === undefined ? [] : match[4].split("."),
+  };
+}
+
+const isNumeric = (id: string): boolean => /^\d+$/.test(id);
+
+function compareIdentifiers(a: string, b: string): -1 | 0 | 1 {
+  const aNum = isNumeric(a);
+  const bNum = isNumeric(b);
+  if (aNum && bNum) {
+    const x = BigInt(a);
+    const y = BigInt(b);
+    return x < y ? -1 : x > y ? 1 : 0;
+  }
+  if (aNum) return -1;
+  if (bNum) return 1;
+  return a < b ? -1 : a > b ? 1 : 0;
+}
